Our interface is implemented by the MemoryOrderRepository class, which provides the
concrete logic of our interface:
using System;
using System.Collections.Generic;
using System.Linq;
using SampleAPI.Models;
namespace SampleAPI.Repositories
{
public class MemoryOrderRepository : IOrderRepository
{
private IList<Order> _orders { get; set; }
public MemoryOrderRepository()
{
_orders = new List<Order>();
}
public IEnumerable<Order> Get() => _orders;
public Order Get(Guid orderId)
{
return _orders.FirstOrDefault(o => o.Id == orderId);
}
public void Add(Order order)
{
_orders.Add(order);
}
Web Service Stack in ASP.NET Core Chapter 5
