public void Update(Guid orderId, Order order)
{
var result = _orders.FirstOrDefault(o => o.Id == orderId);
if (result != null) result.ItemsIds = order.ItemsIds;
}
public Order Delete(Guid orderId)
{
var target = _orders.FirstOrDefault(o => o.Id == orderId);
_orders.Remove(target);
return target;
}
}
}
The MemoryOrderRepository class initializes a private list of the Order type.
Furthermore, it also defines some operations that we can use to manipulate the list of
orders, that are, the Get, Add, Update, and Delete methods. These methods use the LINQ
syntax to act on the list elements. Furthermore, the main collection that's represented by
the _orders attribute is declared as private in order to prevent any external access.
Note that each namespace path reflects the structure of the filesystem. For
